# Security Review: app.js

## Executive Summary
This document provides a comprehensive security review of the provided `app.js` application, identifying vulnerabilities and providing remediation recommendations.

---

## Vulnerabilities Found

### 1. ⚠️ **CRITICAL: Missing Input Validation**
**Severity:** HIGH
**OWASP:** A03:2021 – Injection

**Location:** N/A in current code (endpoints have no user input)

**Description:** The application has no input validation on any endpoint. While not exploited in the current code, this is a critical issue for any future endpoints that accept user input.

**Recommendation:** Implement robust input validation using Web Validation:
```javascript
const { body, validationResult } = require('express-validator');

// Example for a user endpoint
app.get('/users/:id', [
  param('id').isInt({ min: 1 }).withMessage('ID must be a positive integer')
], async (req, res) => {
  // Only proceed if validation passes
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  // ... rest of handler
});
```

---

### 2. ⚠️ **HIGH: Missing Rate Limiting**
**Severity:** MEDIUM
**OWASP:** A05:2021 – Security Misconfiguration

**Location:** Global (no rate limiting applied)

**Description:** The application has no rate limiting, making it vulnerable to:
- DDoS attacks
- Brute force attempts
- Resource exhaustion

**Recommendation:** Implement rate limiting:
```javascript
const rateLimit = require('express-rate-limit');

// General rate limiting
const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later'
  }
});

// Apply to all routes
app.use(generalLimiter);

// More strict limit for specific sensitive endpoints
const sensitiveLimiter = rateLimit({
  windowMs: 60 * 1000, // 1 minute
  max: 5, // limit each IP to 5 requests per minute
  message: {
    error: 'Too many requests, please try again later'
  }
});
```

---

### 3. ⚠️ **HIGH: No Authentication or Authorization**
**Severity:** CRITICAL
**OWASP:** A02:2021 – Cryptographic Failures
**OWASP:** A07:2021 – Identification and Authentication Failures

**Location:** All endpoints (`/health`, `/users`)

**Description:** The application has:
- No authentication mechanism
- No access control
- All endpoints are publicly accessible

**Recommendation:** Implement authentication and authorization:

```javascript
const jwt = require('jsonwebtoken');
const bcrypt = require('bcryptjs');
const { authenticateToken } = require('./middleware/auth');

// JWT Secret (store securely in environment variables)
const JWT_SECRET = process.env.JWT_SECRET || 'CHANGE_ME_STRONG_SECRET';

// Password hashing middleware
async function hashPassword(password) {
  const salt = await bcrypt.genSalt(10);
  return await bcrypt.hash(password, salt);
}

// Authentication middleware
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, JWT_SECRET, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
}

// Protected route example
app.get('/users', authenticateToken, async (req, res) => {
  // Only authenticated users can access user data
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// Registration endpoint (new)
app.post('/register', async (req, res) => {
  const { username, email, password } = req.body;

  // Validate input
  if (!username || !email || !password) {
    return res.status(400).json({ error: 'All fields are required' });
  }

  // Hash password
  const hashedPassword = await hashPassword(password);

  // Store in database (example)
  // await db.users.insert({ username, email, password: hashedPassword });

  res.status(201).json({ message: 'User registered successfully' });
});

// Login endpoint (new)
app.post('/login', async (req, res) => {
  const { email, password } = req.body;

  // Find user in database
  // const user = await db.users.findOne({ email });

  // Verify password
  // const isValid = await bcrypt.compare(password, user.password);

  if (isValid) {
    const token = jwt.sign(
      { id: user.id, email: user.email },
      JWT_SECRET,
      { expiresIn: '1h' }
    );
    res.json({ token, user: { id: user.id, email: user.email } });
  } else {
    res.status(401).json({ error: 'Invalid credentials' });
  }
});
```

---

### 4. **HIGH: Missing CORS Configuration**
**Severity:** MEDIUM
**OWASP:** N/A (but impacts security)

**Location:** Global (no CORS settings)

**Description:** The application accepts requests from any origin, which can allow malicious sites to make requests to your API.

**Recommendation:** Configure CORS properly:
```javascript
const cors = require('cors');

// Development: Allow all origins
// Development: const corsOptions = {
//   origin: ['http://localhost:3000', 'http://localhost:3001'],
//   methods: ['GET', 'POST', 'PUT', 'DELETE'],
//   allowedHeaders: ['Content-Type', 'Authorization'],
//   credentials: true
// };

// Production: Restrict origins
const corsOptions = {
  origin: ['https://yourdomain.com', 'https://app.yourdomain.com'],
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400 // 24 hours
};

app.use(cors(corsOptions));

// Or per-route CORS control
const corsOptionsDelegate = (req, callback) => {
  const corsOptions = {
    origin: '*',
    methods: ['GET']
  };

  callback(null, corsOptions);
};

app.options('/users', cors(corsOptionsDelegate));
app.get('/users', cors(corsOptionsDelegate), authenticateToken, (req, res) => {
  // ...
});
```

---

### 5. **MEDIUM: No Context Security**
**Severity:** MEDIUM
**OWASP:** A01:2021 – Broken Access Control

**Location:** `/users` endpoint

**Description:** The `/users` endpoint returns all users without any filtering or permission checks. A user could potentially access another user's data.

**Recommendation:** Implement role-based access control:
```javascript
// Define role types
const Role = {
  USER: 'user',
  ADMIN: 'admin'
};

// Admin middleware
function requireRole(role) {
  return (req, res, next) => {
    if (!req.user || req.user.role !== role) {
      return res.status(403).json({ error: 'Access denied' });
    }
    next();
  };
}

// Get user by ID with authorization
app.get('/users/:id', authenticateToken, async (req, res) => {
  const { id } = req.params;

  // Users can only access their own data
  // if (req.user.id !== parseInt(id) && req.user.role !== Role.ADMIN) {
  //   return res.status(403).json({ error: 'Access denied' });
  // }

  // Admins can see all users
  // const user = await db.users.findById(id);

  res.json(user);
});

// Get all users (admin only)
app.get('/users', authenticateToken, requireRole(Role.ADMIN), async (req, res) => {
  const users = await db.users.find();
  res.json(users);
});
```

---

### 6. **MEDIUM: Missing Security Headers**
**Severity:** MEDIUM
**OWASP:** A05:2021 – Security Misconfiguration

**Location:** Global response headers

**Description:** The application does not set important security headers that protect against common attacks.

**Recommendation:** Add security headers middleware:
```javascript
const helmet = require('helmet');

// Security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", "data:", "https:"],
      connectSrc: ["'self'"],
      fontSrc: ["'self'"],
      objectSrc: ["'none'"],
      mediaSrc: ["'self'"],
      frameSrc: ["'none'"],
      upgradeInsecureRequests: [],
    },
  },
  hsts: {
    maxAge: 31536000, // 1 year
    includeSubDomains: true,
    preload: true
  }
}));

// Additional custom headers
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
  res.setHeader('Permissions-Policy', 'geolocation=(), microphone=(), camera=()');
  next();
});
```

---

### 7. **MEDIUM: No HTTPS Enforcement**
**Severity:** HIGH
**OWASP:** N/A (infrastructure issue)

**Location:** Server configuration

**Description:** The application runs on HTTP only. All data transmitted between client and server is unencrypted.

**Recommendation:** Use TLS/HTTPS:
```javascript
const fs = require('fs');
const https = require('https');

const httpsOptions = {
  key: fs.readFileSync('./server.key'),
  cert: fs.readFileSync('./server.crt')
};

// Redirect HTTP to HTTPS
app.use((req, res, next) => {
  if (!req.secure && req.headers['x-forwarded-proto'] !== 'https') {
    return res.redirect(301, 'https://' + req.headers.host + req.url);
  }
  next();
});

// Start HTTPS server
https.createServer(httpsOptions, app).listen(443, () => {
  console.log('HTTPS server running on port 443');
});
```

---

### 8. **LOW: No Database Connection Security**
**Severity:** MEDIUM
**OWASP:** A04:2021 – Insecure Design
**OWASP:** A02:2021 – Cryptographic Failures

**Location:** N/A (no database in current code)

**Description:** If a database is added in the future, it would need proper protection.

**Recommendation:** Use secure database practices:
```javascript
const mysql = require('mysql2/promise');
const { dbConfig } = require('./config/db');

// Connection pooling with SSL
const pool = mysql.createPool({
  ...dbConfig,
  waitForConnections: true,
  connectionLimit: 10,
  queueLimit: 0,
  ssl: {
    rejectUnauthorized: true // Enforce SSL
  }
});

// Use parameterized queries to prevent SQL injection
const getUserById = async (userId) => {
  // Good - parameterized query
  const [rows] = await pool.query(
    'SELECT id, name, email FROM users WHERE id = ?',
    [userId]
  );
  return rows[0];
};

// Bad - never do this
// const [rows] = await pool.query(
//   `SELECT * FROM users WHERE id = ${userId}`
// );
```

---

### 9. **LOW: Missing Logging and Monitoring**
**Severity:** MEDIUM
**OWASP:** A05:2021 – Security Misconfiguration

**Location:** None currently

**Description:** No logging makes it difficult to detect security incidents.

**Recommendation:** Implement security logging:
```javascript
const morgan = require('morgan');

// Security-focused logging
const securityMorgan = morgan('combined', {
  stream: fs.createWriteStream('./logs/requests.log', { flags: 'a' })
});

// Log high-risk events
function logSecurityEvent(req, res) {
  if (res.statusCode >= 400) {
    const logEvent = {
      timestamp: new Date().toISOString(),
      ip: req.ip,
      method: req.method,
      path: req.originalUrl,
      statusCode: res.statusCode,
      userAgent: req.get('user-agent'),
      error: req.body.error || 'N/A'
    };
    fs.appendFileSync('./logs/security.log', JSON.stringify(logEvent) + '\n');
  }
}

app.use(securityMorgan);
app.use(logSecurityEvent);

// Security event handler middleware
app.use((req, res, next) => {
  // Log request details
  console.log(`${new Date().toISOString()} - ${req.method} ${req.url} from ${req.ip}`);

  // Monitor failed login attempts
  // You could track this and lock accounts after multiple failures

  next();
});
```

