# Security Review Report for app.js

## Executive Summary
The application has **critical security issues** that must be addressed before deployment. While the code is relatively simple, it contains several security vulnerabilities.

---

## 🚨 CRITICAL VULNERABILITIES

### 1. **No Authentication & Authorization (OWASP A01:2021 - Broken Access Control)**

**Issue:** Anyone can access all endpoints.

**Risk:** High - Data exposure, unauthorized system access.

**Recommended Fix:**
```javascript
// Install required packages: npm install jsonwebtoken bcryptjs helmet express-rate-limit

const jwt = require('jsonwebtoken');
const bcrypt = require('bcryptjs');
const rateLimit = require('express-rate-limit');

// Generate a secure JWT secret (create this file securely!)
const JWT_SECRET = process.env.JWT_SECRET || 'CHANGE_THIS_IN_PRODUCTION';

// Password hashing config
const SALT_ROUNDS = 12;

// Rate limiting middleware
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100 // limit each IP to 100 requests per windowMs
});

// Apply to all routes
app.use(limiter);

// Authentication middleware
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    return res.status(401).json({ error: 'Access token missing' });
  }

  jwt.verify(token, JWT_SECRET, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
};

// Protected route example
app.get('/profile', authenticateToken, (req, res) => {
  res.json({
    status: 'ok',
    user: {
      id: req.user.id,
      name: req.user.name,
      email: req.user.email
    }
  });
});

// Login endpoint with password hashing
app.post('/login', async (req, res) => {
  try {
    const { email, password } = req.body;

    // Input validation (see section 2)
    if (!validateEmail(email) || !password) {
      return res.status(400).json({ error: 'Invalid credentials' });
    }

    // In a real app, fetch user from database
    // For demo, using hardcoded user (REPLACE with real DB)
    const user = { id: 1, email: 'alice@example.com' };

    // Verify password (user passwords should be in database)
    // const validPassword = await bcrypt.compare(password, user.passwordHash);

    // Mock password check (needs replacement)
    if (email === 'alice@example.com' && password === 'alice123') {
      const token = jwt.sign(
        { id: user.id, email: user.email },
        JWT_SECRET,
        { expiresIn: '1h' }
      );
      res.json({ token, userId: user.id });
    } else {
      // Use rate limiting to prevent brute force
      res.status(401).json({ error: 'Invalid credentials' });
    }
  } catch (error) {
    res.status(500).json({ error: 'Internal server error' });
  }
});
```

---

### 2. **Missing Input Validation (OWASP A02:2021 - Cryptographic Failures)**

**Issue:** No validation of user inputs - they could cause crashes or security issues.

**Recommended Fix:**
```javascript
// Create a validation utility file: validators.js
const { body, validationResult } = require('express-validator');

// Helper validator functions
const validateEmail = (email) => {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return emailRegex.test(email);
};

const validatePassword = (password) => {
  return password && password.length >= 8 &&
    password.match(/[A-Z]/) && // At least one uppercase
    password.match(/[a-z]/) && // At least one lowercase
    password.match(/[0-9]/) && // At least one digit
    password.match(/[^A-Za-z0-9]/); // At least one special character
};

// Express validator middleware
const loginValidation = [
  body('email')
    .trim()
    .normalizeEmail()
    .matches(/^[^\s@]+@[^\s@]+\.[^\s@]+$/)
    .withMessage('Invalid email format'),

  body('password')
    .notEmpty()
    .withMessage('Password is required')
    .isLength({ min: 8 })
    .withMessage('Password must be at least 8 characters')
    .matches(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&]).*$/)
    .withMessage('Password must contain uppercase, lowercase, number and special character'),

  (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    next();
  }
];

// User creation validation
const createUserValidation = [
  body('name')
    .trim()
    .isLength({ min: 2, max: 50 })
    .withMessage('Name must be between 2 and 50 characters')
    .escape(), // Prevent XSS in output

  body('email')
    .trim()
    .normalizeEmail()
    .isEmail()
    .withMessage('Invalid email format')
    .custom((value, { req }) => {
      // Email should not contain suspicious characters
      if (/[<>]/.test(value)) {
        throw new Error('Email contains invalid characters');
      }
      return true;
    }),

  body('password')
    .isStrongPassword({
      minLength: 12,
      minLowercase: 1,
      minUppercase: 1,
      minNumbers: 1,
      minSymbols: 1
    })
    .withMessage('Password must be strong: 12+ chars, uppercase, lowercase, number, and symbol'),

  (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    next();
  }
];

module.exports = {
  validateEmail,
  validatePassword,
  loginValidation,
  createUserValidation
};
```

---

### 3. **No Rate Limiting (OWASP A07:2021 - Identification and Authentication Failures)**

**Issue:** Vulnerable to brute force, DDoS, and excessive request attacks.

**Recommended Fix:**
```javascript
const rateLimit = require('express-rate-limit');
const ExpressBrute = require('express-brute');

// Basic rate limiter for all requests
const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests, please try again later' }
});

// Strict rate limiter for authentication endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 5, // 5 attempts per 15 minutes
  skipSuccessfulRequests: true, // Don't count successful logins
  message: { error: 'Too many failed login attempts. Please try again later' }
});

// Apply to all routes
app.use(generalLimiter);

// Apply specifically to auth endpoints
app.post('/login', authLimiter, async (req, res) => {
  // ... login logic
});

// Or use ExpressBrute for more complex rate limiting
const mongoStore = new ExpressBrute.Store(new MongoStore({
  uri: process.env.MONGODB_URI
}));

const bruteforceLimiter = new ExpressBrute(mongoStore, {
  freeStorage: 1, // Max failed attempts before delayed
  minWait: 15 * 1000, // First delay: 15 seconds
  maxWait: 60 * 60 * 1000, // Max delay: 1 hour
  failCallback: (req, res, next, nextValidRequestDate) => {
    const secondsLeft = Math.ceil((nextValidRequestDate.getTime() - Date.now()) / 1000);
    res.status(429).json({
      error: `Too many attempts, please try again in ${secondsLeft} seconds`
    });
  }
});

app.post('/brute-login', bruteforceLimiter, (req, res) => {
  // ... login logic
});
```

---

## ⚠️ HIGH RISK VULNERABILITIES

### 4. **CORS Misconfiguration (OWASP A05:2021 - Security Misconfiguration)**

**Issue:** No CORS policy - anyone can make cross-origin requests.

**Recommended Fix:**
```javascript
const cors = require('cors');

// In production, be specific about which domains can access your API
const corsOptions = {
  origin: process.env.NODE_ENV === 'production'
    ? ['https://yourdomain.com'] // Whitelist your domain
    : ['http://localhost:3000', 'http://localhost:5173', 'http://localhost:3001'], // Development

  credentials: true, // Allow cookies and authorization headers
  optionsSuccessStatus: 200, // Respond to preflight requests with 200
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization']
};

app.use(cors(corsOptions));

// More secure: specific routes with CORS
const corsSpecific = cors({
  origin: 'https://trusted-domain.com',
  methods: ['GET'],
  allowedHeaders: ['Authorization']
});

app.get('/public-data', corsSpecific, (req, res) => {
  res.json({ public: 'data' });
});
```

---

### 5. **No Input Sanitization (OWASP A03:2021 - Injection)**

**Issue:** No sanitization - potential security risks from crafted inputs.

**Recommended Fix:**
```javascript
const { body, param, query, validationResult } = require('express-validator');
const xss = require('xss');
const validator = require('validator');

// Comprehensive sanitization middleware
const sanitizeMiddleware = (req, res, next) => {
  const sanitize = (obj) => {
    if (typeof obj !== 'object' || obj === null) return obj;

    Object.keys(obj).forEach(key => {
      const value = obj[key];

      // Sanitize strings
      if (typeof value === 'string') {
        // Remove or escape HTML
        obj[key] = xss(value);

        // Validate against potential injection
        if (key === 'query' || key === 'search') {
          // Only allow safe characters
          obj[key] = validator.escape(value.trim());
        }
      }

      // Recursively sanitize arrays and objects
      if (Array.isArray(value)) {
        obj[key] = value.map(sanitize);
      } else if (typeof value === 'object') {
        obj[key] = sanitize(value);
      }
    });

    return obj;
  };

  req.body = sanitize(req.body);
  req.query = sanitize(req.query);
  req.params = sanitize(req.params);

  next();
};

app.use(sanitizeMiddleware);

// Example route with parameter validation
app.get('/search', [
  query('q')
    .trim()
    .escape()
    .isLength({ min: 3, max: 100 })
    .withMessage('Search term must be between 3 and 100 characters')
    // Restrict to alphanumeric and spaces
    .matches(/^[a-zA-Z0-9\s-]*$/)
    .withMessage('Search contains invalid characters'),
], (req, res) => {
  const searchQuery = req.query.q;
  // Use sanitized query
});
```

---

### 6. **No Data Encryption (OWASP A02:2021)**

**Issue:** No encryption for sensitive data.

**Recommended Fix:**
```javascript
const crypto = require('crypto');

// Token generation
function generateSecureToken(length = 32) {
  return crypto.randomBytes(length).toString('hex');
}

// Hash sensitive data (passwords)
async function hashPassword(password) {
  const salt = await bcrypt.genSalt(SALT_ROUNDS);
  return bcrypt.hash(password, salt);
}

// Verify password
async function verifyPassword(password, hash) {
  return bcrypt.compare(password, hash);
}

// Encrypt sensitive data
function encryptData(data, secret) {
  const iv = crypto.randomBytes(16);
  const cipher = crypto.createCipheriv('aes-256-gcm', Buffer.from(secret), iv);

  let encrypted = cipher.update(data, 'utf8', 'hex');
  encrypted += cipher.final('hex');

  const authTag = cipher.getAuthTag();

  return {
    iv: iv.toString('hex'),
    authTag: authTag.toString('hex'),
    encryptedData: encrypted
  };
}

// Decrypt sensitive data
function decryptData(encryptedData, secret) {
  const decipher = crypto.createDecipheriv(
    'aes-256-gcm',
    Buffer.from(secret),
    Buffer.from(encryptedData.iv, 'hex')
  );

  decipher.setAuthTag(Buffer.from(encryptedData.authTag, 'hex'));

  let decrypted = decipher.update(encryptedData.encryptedData, 'hex', 'utf8');
  decrypted += decipher.final('utf8');

  return decrypted;
}

// Example usage
app.post('/register', async (req, res) => {
  try {
    const { password } = req.body;

    // Hash the password before storing
    const passwordHash = await hashPassword(password);

    // In production, encrypt sensitive data before saving to DB
    // const sensitiveData = encryptData(user.ssn, process.env.ENCRYPTION_SECRET);

    // Store encrypted password in database
    // await db.users.create({ passwordHash: passwordHash });
  } catch (error) {
    res.status(500).json({ error: 'Registration failed' });
  }
});
```

---

## 🟡 MEDIUM RISK VULNERABILITIES

### 7. **No Content Security Policy (CSP) (OWASP A05:2021)**

**Issue:** No CSP - vulnerable to XSS and data exfiltration.

**Recommended Fix:**
```javascript
const helmet = require('helmet');

// Basic secure headers
app.use(helmet());

// Custom Content Security Policy
const contentSecurityPolicy = helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
