  console.log('🟢 Production environment detected');
} else if (process.env.NODE_ENV === 'test') {
  console.log('🟡 Test environment detected');
} else {
  console.log('❌ NODE_ENV not set, defaulting to development');
  console.warn('⚠️  For production, set NODE_ENV=production');
}
```

### Phase 5: AWS Secrets Manager Integration (Production Best Practice)

Create `secrets-manager.js`:

```javascript
// SECURITY: NEVER COMMIT THIS FILE
// This demonstrates proper AWS Secrets Manager usage

const AWS = require('aws-sdk');

// Initialize Secrets Manager
const secretsManager = new AWS.SecretsManager({
  region: process.env.AWS_REGION || 'us-east-1'
});

// Cache secrets to reduce AWS API calls
let cachedSecrets = null;
let refreshTimer = null;

async function getSecrets() {
  const secretName = process.env.SECRET_NAME || 'production/app-secrets';

  // Check cache
  if (cachedSecrets && refreshTimer) {
    return cachedSecrets;
  }

  try {
    console.log(`Fetching secret from AWS Secrets Manager...`);

    const data = await secretsManager.getSecretValue({ SecretId: secretName }).promise();

    cachedSecrets = JSON.parse(data.SecretString);

    // Cache until 10 minutes before expiration
    if (data.ExpiresOn) {
      const expirationDate = new Date(data.ExpiresOn);
      const now = new Date();
      const timeout = expirationDate - now - (60000 * 10);

      if (timeout > 0) {
        refreshTimer = setTimeout(() => {
          cachedSecrets = null;
          getSecrets();
        }, timeout);
      }
    }

    return cachedSecrets;
  } catch (error) {
    console.error('Error fetching secret from AWS Secrets Manager:', error);

    // Fallback to environment variables
    if (!process.env.IGNORE_MISSING_SECRET) {
      console.error('⚠️  Falling back to .env file');
    }

    // Merge with environment variables (env vars have priority)
    return {
      ...getEnvironmentSecrets(),
      ...process.env
    };
  }
}

function getEnvironmentSecrets() {
  return {
    DATABASE_URL: process.env.DATABASE_URL,
    JWT_SECRET: process.env.JWT_SECRET,
    // etc.
  };
}

module.exports = {
  getSecrets,
  secretsManager
};
```

Update `app_secure.js` to use it:

```javascript
// At the top of app_secure.js
const { getSecrets } = require('./secrets-manager');

async function initApp() {
  try {
    // Fetch secrets from secure source
    const secrets = await getSecrets();

    // Verify critical secrets exist
    if (!secrets.JWT_SECRET) {
      throw new Error('JWT_SECRET not found in secrets');
    }

    // Set them as environment variables
    process.env.JWT_SECRET = secrets.JWT_SECRET;
    process.env.DATABASE_URL = secrets.DATABASE_URL;
    // ... validate other critical secrets

    console.log('✅ All secrets loaded successfully');

    // Start server only after secrets are loaded
    startServer();
  } catch (error) {
    console.error('Critical error initializing secret management:', error);
    process.exit(1);
  }
}

// Call this instead of directly app.listen()
initApp();
```

