    } catch (error) {
      console.error('Secret rotation failed:', error);
    }
  });
}

// And JWT expiry handling
const jwt = require('jsonwebtoken');

const JWT_CONFIG = {
  secret: process.env.JWT_SECRET,
  expiresIn: '90d'  // Rotate keys every 3 months
};

function decodeToken(token) {
  try {
