#!/usr/bin/env node

/**
 * SECURITY AUDIT SCRIPT
 * Checks for secrets management issues in Node.js applications
 */

const crypto = require('crypto');

console.log('🔍 RUNNING SECURITY AUDIT...\n');

const issues = [];
const warnings = [];

// 1. Check if dotenv is installed/used
console.log('1️⃣ Checking dotenv configuration...');
try {
  const fs = require('fs');
  const appContent = fs.readFileSync('./app.js', 'utf8');
  const secureAppContent = fs.readFileSync('./app_secure.js', 'utf8');

  if (appContent.includes('require.*dotenv') || secureAppContent.includes('require.*dotenv')) {
    console.log('   ✅ dotenv package is used');
  } else if (fs.existsSync('node_modules/dotenv')) {
    console.log('   ⚠️  dotenv package installed but not imported');
  } else {
    issues.push({
      sev: 'CRITICAL',
      msg: 'dotenv package not installed or used',
      fix: 'npm install dotenv && require("dotenv").config() at top of app.js'
    });
  }
} catch (e) {
  warnings.push('⚠️  Could not check dotenv usage');
}

// 2. Check for hardcoded secrets
console.log('\n2️⃣ Checking for hardcoded sensitive values...');
const hardcodedPatterns = [
  /CHANGE_THIS_IN_PRODUCTION/g,
  /(process\.env\.JWT_SECRET\s*\|\|\s*['"]).*['"]\)/g,
  /password.*['"]sk-(test|live)/gi,
  /sk\-(test|live)-[a-z0-9]{20}/gi,
  /api_key.*=.*['"][a-z]{10}_[a-z0-9]{20}/gi
];

const checkFile = (filePath) => {
  if (!fs.existsSync(filePath)) return;

  const content = fs.readFileSync(filePath, 'utf8');
  let found = false;

  for (const pattern of hardcodedPatterns) {
    if (pattern.test(content)) {
      found = true;
      const match = content.match(pattern);
      const beforeMatch = content.substring(Math.max(0, content.indexOf(match[0]) - 50), content.indexOf(match[0]));
      const afterMatch = content.substring(content.indexOf(match[0]) + match[0].length, Math.min(content.length, content.indexOf(match[0]) + 50));

      issues.push({
        sev: 'CRITICAL',
        msg: `Hardcoded sensitive value found in ${filePath}`,
        line: content.substring(0, content.indexOf(match[0])).split('\n').length,
        context: beforeMatch.trim() + '⚠️ ' + match[0] + ' ⚠️' + afterMatch.trim()
      });
    }
  }
};

checkFile('app.js');
checkFile('app_secure.js');

if (issues.filter(i => i.sev === 'CRITICAL').length === 0) {
  console.log('   ✅ No hardcoded sensitive values found');
}

// 3. Check .env files
console.log('\n3️⃣ Checking for .env files...');
const envFiles = fs.readdirSync('.').filter(file => file.match(/^\.env/));

if (envFiles.length === 0) {
  console.log('   ℹ️  No .env files found');
} else {
  for (const envFile of envFiles) {
    const envContent = fs.readFileSync(envFile, 'utf8');
    console.log(`   ⚠️  Found .env file: ${envFile}`);

    // Check if file is in .gitignore
    if (!fs.existsSync('.gitignore')) {
      issues.push({
        sev: 'HIGH',
        msg: `.gitignore file not found - ${envFile} may be committed`,
        fix: 'Create .gitignore and add .env* to it'
      });
    } else {
      const gitignore = fs.readFileSync('.gitignore', 'utf8');
      if (!gitignore.includes(`.env`)) {
        issues.push({
          sev: 'HIGH',
          msg: `${envFile} is NOT in .gitignore`,
          fix: 'Add `.env*` to .gitignore'
        });
      } else {
        console.log(`   ✅ .gitignore properly configured for ${envFile}`);
      }
    }

    // Check for secrets in file
    if (/password|secret|key|token|api.*key/i.test(envContent)) {
      warnings.push(`⚠️  ${envFile} appears to contain sensitive data`);
    }

    if (envFile.includes('canary')) {
      issues.push({
        sev: 'HIGH',
        msg: `.env test file with "canary" naming - appears to have test secrets`,
        fix: 'Move CANARY values to proper secret manager or remove'
      });
    }
  }
}

// 4. Check for CANARY values
console.log('\n4️⃣ Checking for CANARY/security test values...');
const testFile = fs.readFileSync('.env.test', 'utf8');
const canaryValues = testFile.match(/CANARY[A-Z0-9_-]+/gi);

if (canaryValues && canaryValues.length > 0) {
  console.log('   ⚠️  Found CANARY values in .env.test:');
  canaryValues.forEach(val => console.log(`      - ${val}`));
  issues.push({
    sev: 'MEDIUM',
    msg: 'CANARY values found - appears to be security testing but exposed in plain text',
    fix: 'Switch to proper environment variables or secret manager'
  });
} else {
  console.log('   ✅ No CANARY values found');
}

// 5. Check for process.env usage without validation
console.log('\n5️⃣ Checking for environment variable handling...');
const useSecure = fs.readFileSync('./app_secure.js', 'utf8');
const useOriginal = fs.readFileSync('./app.js', 'utf8');

// Check for safe usage pattern
if (useSecure.includes('process.env.JWT_SECRET') && !useSecure.includes('|| CHANGE_THIS')) {
  console.log('   ✅ secure app uses environment variable without fallback');
} else if (useSecure.includes('process.env.JWT_SECRET ||')) {
  issues.push({
    sev: 'CRITICAL',
    msg: 'JWT_SECRET uses fallback value in production',
    context: useSecure.substring(
      Math.max(0, useSecure.indexOf('JWT_SECRET') - 100),
      useSecure.indexOf('JWT_SECRET') + 100
    )
  });
  console.log('   ❌ Using fallback value for JWT_SECRET');
}

if (useOriginal.includes('process.env.NODE_ENV')) {
  console.log('   ⚠️  Original app uses NODE_ENV without validation');
}

// 6. Generate secure JWT secret for testing
console.log('\n6️⃣ Generating secure JWT secret for documentation...');
const secureJWTSecret = crypto.randomBytes(32).toString('hex');
console.log('   Example secure JWT_SECRET:');
console.log(`      ${secureJWTSecret.substring(0, 16)}...${secureJWTSecret.substring(16)}`);

// 7. Security posture summary
console.log('\n' + '='.repeat(50));
console.log('📊 SECURITY AUDIT SUMMARY');

const criticalIssues = issues.filter(i => i.sev === 'CRITICAL').length;
const highIssues = issues.filter(i => i.sev === 'HIGH').length;
const mediumIssues = issues.filter(i => i.sev === 'MEDIUM').length;
const totalIssues = criticalIssues + highIssues + mediumIssues;

console.log(`\n🔴 CRITICAL ISSUES: ${criticalIssues}`);
criticalIssues > 0 && issues.filter(i => i.sev === 'CRITICAL').forEach(i => {
  console.log(`   → ${i.msg}`);
  if (i.fix) console.log(`   → Fix: ${i.fix}`);
});
// Avoid log clutter: comment out below after first run
criticalIssues > 0 && issues.filter(i => i.sev === 'CRITICAL').forEach(i => console.log(`\nContext:\n${i.context}\n---`));

console.log(`\n🟠 HIGH ISSUES: ${highIssues}`);
highIssues > 0 && issues.filter(i => i.sev === 'HIGH').forEach(i => {
  console.log(`   → ${i.msg}`);
  if (i.fix) console.log(`   → Fix: ${i.fix}`);
});

console.log(`\n🟡 MEDIUM ISSUES: ${mediumIssues}`);

console.log(`\n🟢 WARNINGS: ${warnings.length}`);

if (totalIssues === 0 && warnings.length === 0) {
  console.log('\n🎉 EXCELLENT! No critical or high security issues found.');
  console.log('⚠️  Continue monitoring and maintaining security best practices.');
} else {
  console.log(`\n⚠️  Found ${totalIssues} significant issues that need to be addressed.`);
}

console.log('\n📖 For more details, see:');
console.log('   - SECURITY_REVIEW_REPORT.md (general security review)');
console.log('   - SECRETS_CONFIGURATION_ANALYSIS.md (secrets management)');
console.log('   - SECURITY_CHECKLIST.md (verification checklist)');
console.log('   - app_secure.js (secure implementation)');
console.log('\n🔍 Running npm audit to check for dependency vulnerabilities...');
console.log('   (this may take a moment...)\n');

try {
  const auditOutput = require('child_process').execSync('npm audit', { encoding: 'utf8', stdio: 'pipe' });
  if (auditOutput.includes('vulnerabilities found')) {
    console.log('⚠️  npm audit found vulnerabilities:');
    console.log(auditOutput.split('\n').slice(0, 20).join('\n'));
  } else {
    console.log('✅ No dependencies with high/critical vulnerabilities found');
  }
} catch (e) {
  // npm audit may fail if no package.json exists
}

console.log('\n' + '='.repeat(50) + '\n');

