// 🔒 Secure Version of app.js
// Security best practices applied:

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const xss = require('xss-clean');
const { body, validationResult } = require('express-validator');

const app = express();

// ==========================================
// SECURITY MIDDLEWARE STACK
// ==========================================

// 1. Helmet - security headers
app.use(helmet({
  contentSecurityPolicy: false, // Disabled to allow JSON responses
}));

// 2. Rate Limiting - prevents DDoS and brute force
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per window
  message: {
    error: 'Too many requests from this IP, please try again later.',
    retryAfter: 900
  },
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/api/', limiter); // Apply to all /api routes

// 3. Body parser security
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// 4. Data sanitization against XSS
app.use(xss());

// 5. CORS configuration
const corsOptions = {
  origin: process.env.NODE_ENV === 'production'
    ? process.env.ALLOWED_ORIGINS?.split(',') || ['https://yourdomain.com']
    : true, // Allow all in development
  methods: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization', 'X-Requested-With'],
  credentials: true,
  maxAge: 86400,
};
app.use(cors(corsOptions));

// ==========================================
// INPUT VALIDATION
// ==========================================

const validate = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array()
    });
  }
  next();
};

// ==========================================
// ROUTES
// ==========================================

// Health check endpoint (no auth required but rate limited)
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
    node_version: process.version
  });
});

// API v1 prefix
app.use('/api/v1', (req, res, next) => {
  req.startTime = Date.now();
  next();
});

// Users endpoints
app.get('/api/v1/users', validate, (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

app.get(
  '/api/v1/users/:id',
  [
    body('id')
      .isInt({ min: 1 })
      .withMessage('User ID must be a positive integer')
  ],
  validate,
  (req, res) => {
    const userId = parseInt(req.params.id);
    res.json({ id: userId, name: `User ${userId}`, email: `user${userId}@example.com` });
  }
);

// Protected API routes
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader?.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.JWT_SECRET || 'fallback-secret-for-dev-only', (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
};

// This requires JWT_SECRET to be set
// app.get('/api/v1/protected', authenticateToken, (req, res) => {
//   res.json({
//     message: 'This is protected data',
//     user: req.user
//   });
// });

// ==========================================
// ERROR HANDLING
// ==========================================

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Endpoint not found' });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error('Error:', err.stack);

  const statusCode = err.statusCode || 500;
  const message = err.message || 'Internal Server Error';

  // Do not expose stack trace in production
  const errorResponse = {
    error: message
  };

  if (process.env.NODE_ENV === 'development') {
    errorResponse.stack = err.stack;
    errorResponse.details = err.details;
  }

  res.status(statusCode).json(errorResponse);
});

// Request logging middleware (Good practice)
app.use((req, res, next) => {
  const { method, url, ip } = req;
  const userAgent = req.get('user-agent');

  console.log(`${new Date().toISOString()} : ${method} ${url} - ${ip} - ${userAgent}`);

  // Log response time
  res.on('finish', () => {
    const duration = Date.now() - req.startTime;
    console.log(`Response time: ${duration}ms - Status: ${res.statusCode}`);
  });

  next();
});

// ==========================================
// HTTPS ENFORCEMENT (Production only)
// ==========================================
const enforceHTTPS = (req, res, next) => {
  if (process.env.NODE_ENV === 'production' &&
      !req.secure &&
      req.get('x-forwarded-proto') !== 'https') {
    return res.redirect(301, `https://${req.headers.host}${req.originalUrl}`);
  }
  next();
};

app.use(enforceHTTPS);

// ==========================================
// START SERVER
// ==========================================
const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

app.listen(PORT, HOST, () => {
  console.log(`
╔═════════════════════════════════════════╗
║  Secure Server Started on ${HOST}:${PORT}  ║
╠═════════════════════════════════════════╣
║  Environment: ${process.env.NODE_ENV || 'development'}           ║
║  Rate Limiting: Yes                    ║
║  CORS: Enabled                         ║
║  Helmet: Applied                       ║
║  XSS Protection: Enabled               ║
╚═════════════════════════════════════════╝
  `);
});

module.exports = app;

