  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
  res.setHeader('Content-Security-Policy', "default-src 'self'");
  res.setHeader('Permissions-Policy', 'geolocation=(), microphone=(), camera=()');
  next();
});
```

---

### 9. **错误处理 - MEDIUM**
**Vulnerability**: Generic error responses show too much information.
**Impact**: Information disclosure, easier debugging for attackers.

**Recommended Fix - SECURE ERROR HANDLING**:
```javascript
// Custom error handler
app.use((err, req, res, next) => {
  console.error(err.stack);

  const isDevelopment = process.env.NODE_ENV === 'development';

  // Don't expose stack trace in production
  const errorDetails = isDevelopment ? err.stack : undefined;

  res.status(err.status || 500).json({
    error: {
      message: err.message || 'Internal Server Error',
      ...(isDevelopment && { details: errorDetails })
    }
  });
});

// No error in context
app.get('/users/:id', async (req, res, next) => {
  try {
    const user = await db.getUserById(req.params.id);
    if (!user) {
      throw createError(404, 'User not found');
    }
    res.json(user);
  } catch (err) {
    next(err);
  }
});

// Helper function for consistent error responses
function createError(status, message) {
  const error = new Error(message);
  error.status = status;
  error.isOperational = true;
  return error;
}
```

---

### 10. **Missing HTTPS/SSL - LOW**
**Vulnerability**: No HTTPS enforcement.
**Impact**: Credentials and data transmitted in plaintext.

**Recommended Fix - HTTPS**:
```javascript
const https = require('https');
const fs = require('fs');

// For development
if (process.env.NODE_ENV === 'development') {
  app.listen(3000, () => {
    console.log('Server running on port 3000 (HTTP)');
  });
} else {
  // For production
  const httpsOptions = {
    key: fs.readFileSync(process.env.SSL_KEY_PATH || './certs/key.pem'),
    cert: fs.readFileSync(process.env.SSL_CERT_PATH || './certs/cert.pem')
  };

  https.createServer(httpsOptions, app).listen(443, () => {
    console.log('Server running on port 443 (HTTPS)');
  });

  // Redirect HTTP to HTTPS
  const http = require('http');
  http.createServer((req, res) => {
    res.writeHead(301, { Location: `https://${req.headers.host}${req.url}` });
    res.end();
  }).listen(80);
}
```

---

## Full Secure Implementation Example

Here's a complete, secure version of the app.js:

```javascript
'Require': [
  'express',
  'helmet',           // Security headers
  'cors',             // CORS configuration
  'express-rate-limit',// Rate limiting
  'express-validator',// Input validation
  'jsonwebtoken',    // JWT authentication
  'bcrypt',           // Password hashing
  'dotenv'            // Environment variables
]

// Configuration
require('dotenv').config();

// Security constants
const PORT = process.env.PORT || 3000;
const JWT_SECRET = process.env.JWT_SECRET;
if (!JWT_SECRET) {
  console.error('CRITICAL: JWT_SECRET environment variable is required');
  process.exit(1);
}

const app = express();

// Security middleware
app.use(helmet({
  contentSecurityPolicy: false, // Customize separately if needed
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// Rate limiting
app.use('/api/', rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  handler: (req, res) => {
    res.status(429).json({ error: 'Too many requests, please try again later' });
  }
}));

// CORS
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || [],
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true
}));

// Body parsing with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Authentication middleware
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  jwt.verify(token, JWT_SECRET, (err, user) => {
    if (err) {
      if (err.name === 'TokenExpiredError') {
        return res.status(401).json({ error: 'Token expired' });
      }
      return res.status(403).json({ error: 'Invalid token' });
    }
    req.user = user;
    next();
  });
};

// Role-based access control
const checkRole = (...allowedRoles) => {
  return (req, res, next) => {
    if (!req.user || !allowedRoles.includes(req.user.role)) {
      return res.status(403).json({ error: 'Insufficient permissions' });
    }
    next();
  };
};

// Input validation middleware
const validateUserId = (req, res, next) => {
  const id = req.params.id;
  if (!/^[0-9]+$/.test(id)) {
    return res.status(400).json({ error: 'Invalid user ID' });
  }
  next();
};

// Routes
// Health check (public endpoint)
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    version: '1.0.0'
  });
});

// Users endpoint (with authentication)
app.get('/users',
  authenticateToken,
  [validateUserId],
  async (req, res) => {
    try {
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' }
      ];
      res.json(users);
    } catch (error) {
      res.status(500).json({ error: 'Error retrieving users' });
    }
  }
);

// User endpoints (with full authorization)
app.get('/users/:id',
  authenticateToken,
  [validateUserId],
  checkRole('admin'),
  async (req, res) => {
    try {
      const user = await db.getUserById(req.params.id);
      if (!user) {
        return res.status(404).json({ error: 'User not found' });
      }
      res.json(user);
    } catch (error) {
      res.status(500).json({ error: 'Error retrieving user' });
    }
  }
);

// Error handling
app.use((err, req, res, next) => {
  console.error('Error:', err);
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(err.status || 500).json({
    error: {
      message: err.message || 'Internal Server Error',
      ...(isDevelopment && { stack: err.stack })
    }
  });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Route not found' });
});

// Start server
if (process.env.NODE_ENV === 'development') {
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT} (development mode)`);
  });
} else {
  // Production HTTPS setup...
}
```

