```javascript
// lambda/rotate-secrets.js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
const crypto = require('crypto');

exports.handler = async (event) => {
  const client = new SecretsManagerClient({
    region: process.env.AWS_REGION || 'us-east-1'
  });

  try {
    console.log('Starting secret rotation...');

    // Get current secret
    const { SecretString } = await client.send(new GetSecretValueCommand({
      SecretId: process.env.APP_SECRET_ARN
    }));

    const secrets = JSON.parse(SecretString);

    // Generate new secrets
    secrets.JWT_SECRET = crypto.randomBytes(40).toString('base64');
    secrets.DB_PASSWORD = generatePassword(32);

    // Update secret
    await client.send(new PutSecretValueCommand({
      SecretId: process.env.APP_SECRET_ARN,
      SecretString: JSON.stringify(secrets)
    }));

    console.log('✅ Secret rotation completed successfully');
    return { status: 'success' };
  } catch (error) {
    console.error('🔴 Secret rotation failed:', error);
    return { status: 'failed', error: error.message };
  }
};

function generatePassword(length = 32) {
  const charset = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#%^&*()_+';
  let password = '';
  const values = crypto.randomInt(0, charset.length);
  for (let i = 0; i < length; i++) {
    password += charset[values % charset.length];
    values += crypto.randomInt(0, charset.length);
  }
  return password;
}
