```javascript
// config/secrets.js
const AWS = require('aws-sdk');
require('aws-sdk/lib/credentials');

class SecretManager {
  constructor() {
    this.secretsCache = new Map();
  }

  async get(secretName) {
    // Check cache first
    if (this.secretsCache.has(secretName)) {
      return this.secretsCache.get(secretName);
    }

    let secretValue;

    if (process.env.NODE_ENV === 'production') {
      try {
        const ssm = new AWS.SystemsManager();
        const data = await ssm
          .getParameter({ 
            Name: `/production/${process.env.APP_NAME}/${secretName}`,
            WithDecryption: true 
          })
          .promise();
        secretValue = data.Parameter.Value;
      } catch (error) {
        console.error(`Failed to fetch secret ${secretName}:`, error.message);
        throw error;
      }
    } else {
      // Fallback to env for dev - do not expose in logs
      const envVarName = secretName.toUpperCase().replace(/_/g, '_');
      secretValue = process.env[envVarName];

      if (!secretValue) {
        throw new Error(`Required environment variable not found: ${envVarName}`);
      }
    }

    // Cache and return
    this.secretsCache.set(secretName, secretValue);
    return secretValue;
  }

  clearCache() {
    this.secretsCache.clear();
  }
}

module.exports = new SecretManager();
```

