#### 4. Add Secret Validation Middleware
```javascript
// create/securityCheck.js
const crypto = require('crypto');

/**
 * Validate that a string matches AWS Access Key ID format
 * AWS keys are 20 characters, alphanumeric
 */
function isValidAWSKey(key) {
  return /^AKIA[0-9A-Z]{16}$/.test(key);
}

/**
 * Validate that a string matches JWT secret requirements
 * Should be at least 32 characters long
 */
function isValidJWTSecret(secret) {
  return secret && secret.length >= 32;
}

/**
 * Validate database URL format
 */
function isValidDatabaseUrl(url) {
  try {
    const parsed = new URL(url);
    return parsed.protocol === 'postgres:' || parsed.protocol === 'mysql:';
  } catch (err) {
    return false;
  }
}

/**
 * Read and validate all secrets from environment variables
 */
function validateAllSecrets() {
  const secrets = {
    databaseUrl: process.env.DATABASE_URL,
    jwtSecret: process.env.JWT_SECRET,
    // Add other secrets you use...
  };

  const errors = {};

  // Validate database URL
  if (!secrets.databaseUrl) {
    errors.databaseUrl = 'DATABASE_URL is required';
  } else if (!isValidDatabaseUrl(secrets.databaseUrl)) {
    errors.databaseUrl = 'DATABASE_URL must be a valid PostgreSQL or MySQL connection string';
  }

  // Validate JWT secret
  if (!secrets.jwtSecret) {
    errors.jwtSecret = 'JWT_SECRET is required';
  } else if (!isValidJWTSecret(secrets.jwtSecret)) {
    errors.jwtSecret = 'JWT_SECRET must be at least 32 characters';
  }

  // Validate AWS keys (if used)
  if (process.env.AWS_ACCESS_KEY_ID) {
    if (!isValidAWSKey(process.env.AWS_ACCESS_KEY_ID)) {
      errors.awsAccessKey = 'AWS_ACCESS_KEY_ID must be in format AKIAxxxxxxxxxxxxxxxxxxxx';
    }
  }

  return {
    valid: errors.length === 0,
    errors: errors
  };
}

// Apply validation when server starts
const validation = validateAllSecrets();
if (!validation.valid) {
  console.error('❌ Secrets validation failed:');
  Object.entries(validation.errors).forEach(([key, error]) => {
    console.error(`   ${key}: ${error}`);
  });
  process.exit(1);
}

module.exports = { validateAllSecrets, isValidAWSKey, isValidJWTSecret };
```

---

